<?php
declare(strict_types=1);namespace App\Repositories;use App\Core\TenantContext;use PDO;
final class InvitationQuestionRepository{public function __construct(private readonly PDO $pdo){}public function activePublic(int $c,int $i):array{$s=$this->pdo->prepare('SELECT id,label,question_type,options_json,is_required FROM invitation_form_questions WHERE church_id=:church_id AND invitation_id=:invitation_id AND is_active=1 ORDER BY sort_order,id LIMIT 30');$s->execute(['church_id'=>$c,'invitation_id'=>$i]);return$s->fetchAll();}public function listForTenant(TenantContext $t,int $i):array{$s=$this->pdo->prepare('SELECT q.* FROM invitation_form_questions q JOIN invitations i ON i.id=q.invitation_id AND i.church_id=q.church_id WHERE q.church_id=:church_id AND q.invitation_id=:invitation_id ORDER BY q.sort_order,q.id LIMIT 50');$s->execute(['church_id'=>$t->churchId(),'invitation_id'=>$i]);return$s->fetchAll();}public function save(TenantContext $t,int $inv,int $id,array $d):int{$p=['church_id'=>$t->churchId(),'invitation_id'=>$inv,'label'=>$d['label'],'type'=>$d['question_type'],'options'=>$d['options_json'],'required'=>$d['is_required'],'sort'=>$d['sort_order']];if($id>0){$s=$this->pdo->prepare('UPDATE invitation_form_questions SET label=:label,question_type=:type,options_json=:options,is_required=:required,sort_order=:sort,is_active=1 WHERE id=:id AND church_id=:church_id AND invitation_id=:invitation_id');$s->execute($p+['id'=>$id]);return$s->rowCount()?$id:0;}$s=$this->pdo->prepare('INSERT INTO invitation_form_questions(church_id,invitation_id,label,question_type,options_json,is_required,sort_order) VALUES(:church_id,:invitation_id,:label,:type,:options,:required,:sort)');$s->execute($p);return(int)$this->pdo->lastInsertId();}public function deactivate(TenantContext $t,int $i,int $id):bool{$s=$this->pdo->prepare('UPDATE invitation_form_questions SET is_active=0 WHERE id=:id AND church_id=:church_id AND invitation_id=:invitation_id');$s->execute(['id'=>$id,'church_id'=>$t->churchId(),'invitation_id'=>$i]);return$s->rowCount()===1;}}
